set-variable.value:
@{
		var source = context.LastError?.Source ?? "";
		if (source == "validate-azure-ad-token") { return 401; }
		if (source == "rate-limit" || source == "quota") { return 429; }
		if (context.Response != null && context.Response.StatusCode >= 400) { return context.Response.StatusCode; }
		return 500;
	}

@{
		var s = (int)context.Variables["http-status"];
		if (s == 401) { return "unauthorized"; }
		if (s == 403) { return "forbidden"; }
		if (s == 429) { return "rate_limited"; }
		if (s < 500) { return "bad_request"; }
		return "gateway_error";
	}
